pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint8 count, address recipient, uint96 amount) public {
        // Deploy and initialize required dependencies
        VaderMock vader = new VaderMock();
        UsdvMock usdv = new UsdvMock();
        VaultMock vault = new VaultMock();
        c.init(address(vader), address(usdv), address(vault));

        // Bound count to a reasonable range to avoid excessive gas usage
        uint8 n = uint8(bound(count, 1, 50));

        // Make n calls to newGrantProposal
        for (uint8 i = 0; i < n; i++) {
            vm.prank(address(uint160(i + 1)));
            c.newGrantProposal(recipient, uint256(amount));
        }

        // The property: proposalCount must equal the number of calls made (n)
        assertEq(c.proposalCount(), n);
    }
}

