// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address recipient, uint amount) public {
        vm.assume(recipient != address(0));
        address vader = address(0x1);
        address usdv = address(0x2);
        address vault = address(0x3);
        c.init(vader, usdv, vault);
        uint oldCount = c.proposalCount();
        c.newGrantProposal(recipient, amount);
        uint newCount = c.proposalCount();
        assertTrue(newCount > oldCount);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function test(address _vader, address _usdv, address _vault, address _proposedUtils) public {
        c.init(_vader, _usdv, _vault);
        c.newAddressProposal(_proposedUtils, "UTILS");
        uint pid = c.proposalCount();
        c.voteProposal(pid);
        c.finaliseProposal(pid);
        bool finalised = c.mapPID_finalised(pid);
        assert(_vader != address(0) ? finalised : !finalised);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address _vader, address _usdv, address _vault, address _addr) public payable {
        require(_vader != address(0));
        c.init(_vader, _usdv, _vault);
        c.newAddressProposal(_addr, 'UTILS');
        uint pid = c.proposalCount();
        c.finaliseProposal(pid);
        bool reverted = false;
        assembly { reverted := iszero(eq(returndatasize(), 0x20)) }
        assert(reverted == false);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address _vader, address _usdv, address _vault) public payable {
        require(true);
        c.init(_vader, _usdv, _vault);
        assert(c.VADER() == _vader);
    }
    receive() external payable {}
}
